INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(352200, 0, 3522, 0, 0, 8, 'Blade''s Edge Mountains', 'The Blade''s Edge Mountains are a maze of red canyons in the north of Outland, crowned by great curving spikes of stone. This is gronn country. Gruul the Dragonkiller, who once tore the black dragonflight from the sky and left its bones on the spires, rules from his lair in the north, and his seven sons lord over the Bladespire and Bloodmaul ogres, who fight one another for the gronn''s favor. Newcomers have carved out footholds all the same: the night elves at Sylvanaar, Toshley''s gnomes on the Razor Ridge, the Horde in Thunderlord Stronghold and the Cenarion Expedition at Evergrove, while the half-ogre Mok''Nathal hold out in the east. Arakkoa cults whisper of a coming raven, the Wyrmcult worships the surviving black dragons, and the Burning Legion has raised forge camps on the high terraces, where ogres made wise by strange crystals have found a refuge of their own at Ogri''la.', 'warcraft.wiki.gg/wiki/Blade''s_Edge_Mountains (gronn control the ogres; Wyrmcult worships the remaining black dragons; Ogri''la); warcraft.wiki.gg/wiki/Gruul (dragons impaled on the spires, Dragons'' End); quest 10504 description (Gruul and his seven sons); quest 10607 reward text; npc_text 10926 (Chu''a''lor)'),
(352201, 1, 3522, 1, 0, 8, 'Sylvanaar', 'Sylvanaar is a night elf town in the southwest of the mountains, raised in a short time by elven magic on land its founders found empty. Around it they are coaxing the Living Grove to grow at an unnatural pace, meant to ring the town with a defensive woodland of tranquil beauty. Fey drakes pollinate the grove, treant defenders can be called up from its seedlings, and an ancient of war named Stronglimb Deeproot stands as its chief protector. Commander Skyshadow leads the town, wary of the ogres in the ravine below and of the Horde beyond it. To the south, a tunnel through Blade Tooth Canyon is Sylvanaar''s lifeline to the Harborage in the swamps of Zangarmarsh.', 'warcraft.wiki.gg/wiki/Sylvanaar (night elf settlement in the Living Grove); quest 10487 description (elven magics grew a town and grove in a short time); quest 10504 reward text (land initially found empty); quests 10455, 10456, 10457; quest 10489 (Stronglimb Deeproot, chief defender of the Living Grove); quest 10502 description; quest 10927 description and reward (tunnel, lifeline to the swamp, trade with the Harborage); npc_text 10264 (Skyshadow)'),
(352202, 1, 3522, 2, 0, 8, 'Veil Lashh', 'South of the Living Grove, the Lashh''an arakkoa roost among the trees of Veil Lashh, where tame kaliri flutter about their nests. Their magic unsettles the night elves next door. The Lashh''an tear out clawfuls of their own feathers as reagents, keep tomes of crude pictographs high in the branches and work their rites at circles of power on the ground, and what those rites are for, the elves can only guess. At Sylvanaar, Rina Moonspring suspects that the Lashh''an are behind the grove''s lynxes turning on the town.', 'quest 10555 description and request text (feathers as reagents, spellbooks high in the trees); quest 10556 description and reward text (kaliri spirit, communion spell); quest 10455 description (arakkoa of Veil Lashh suspected); DB spawns: Tame Kaliri, Lashh''an Tome, kneel targets and spell origin in area 3782'),
(352203, 1, 3522, 3, 0, 8, 'Bloodmaul Outpost', 'Bloodmaul Ravine cuts between Sylvanaar and Thunderlord Stronghold, and toward its southern end the Bloodmaul clan holds Bloodmaul Outpost, watched over by the Northmaul and Southmaul towers. The Bloodmaul are known for their brew, a foul swill their brewmasters carry about in barrels and their warriors practically live on. A troll witch doctor named T''chali taught them the craft, and they repaid him by burying him in the ravine. At the far south lies the Draenethyst Mine, where crystals grow naturally from the walls and the Explorers'' League wants samples.', 'quests 10502, 10511 (brewmasters carry the brew to the other ogres), 10512; quest 10542 description (T''chali taught the Bloodmaul to brew, buried); quest 10510 description (Draenethyst Mine at the south end, crystals grow naturally); quest 10525 reward and 10526 description (Thunderspike stolen from the Bladespire, back of the mine); quest 10518 (Northmaul Tower); quest 10543 (Grimnok atop the Southmaul Tower); DB: T''chali 21349 stands in area 3824 Bloodmaul Ravine'),
(352204, 1, 3522, 4, 0, 8, 'Thunderlord Stronghold', 'Thunderlord Stronghold was the seat of the Thunderlord clan until those orcs were made fel orcs by the blood of Mannoroth and abandoned it. The Bladespire ogres moved into the empty halls, and the Horde has since driven them out and holds the town in the old clan''s name. Its warriors still fight ogres on every side, and the scholar Rokgah Bloodgrip hunts the clan''s lost relics to appease its restless dead. The Horde''s dire wolves den on the Jagged Ridge to the south under Rema, the den mother, sharing the slopes with bloodletters that eat and breed without pause. The tunnel of Blades'' Run carries trade to Swamprat Post in Zangarmarsh, and Rexxar has come here seeking his people.', 'warcraft.wiki.gg/wiki/Thunderlord_Stronghold (abandoned after the fel transformation, Bladespire occupation, Horde holds it in honor of the clan, dire wolves under Rema at Jagged Ridge, Rexxar came seeking his race); quest 10486 description; quest 10503 description; quest 10456 description (the Horde brought dire wolves); quest 10690 (Rema); npc_text 10322 (Rokgah); quest 10526 request text (appease the dead spirits); quest 10928 (tunnel, trade with Swamp Rat)'),
(352205, 1, 3522, 5, 0, 8, 'Bladespire Hold', 'Bladespire Hold, down in the ravine west of Thunderlord Stronghold, is the seat of the strongest ogre clan in the mountains. The Bladespire stand highest in the favor of Gruul the Dragonkiller, a place won for them by their crafty chieftain Gorr''Dim, and they keep packs of raptors alongside their brutes and shamans. They once held Thunderlord Stronghold, and the Thunderlord relics lost when the Horde drove them out, a drum, an arrow and a tablet, now lie somewhere in the hold. Gorr''Dim keeps defenders about him who are sworn never to touch the Bloodmaul brew. In a cage at the heart of the hold sits Vindicator Vuuleen of Sylvanaar, who insists he is exactly where he wants to be.', 'quest 10503 description (west, the ones defeated to take the stronghold; ogres and raptors); quest 10504 description (strongest clan, favor of Gruul); quest 10517 description (Gorr''Dim elevated his clan, sober defenders); npc_text 10322 and quest 10524 (drum, arrow, tablet in Bladespire Hold); npc_text 10300 and quest 10516 (Vuuleen wants to stay in the cage); DB spawns: Bladespire Brute, Shaman, Raptor, Sober Defender in 3773'),
(352206, 1, 3522, 6, 0, 8, 'Toshley''s Station', 'When the night elves of Sylvanaar sent the gnome Toshley and his followers away over their machines and experiments, the gnomes climbed to the Razor Ridge and built Toshley''s Station, where they can experiment as they please. The station is a clutter of laboratories and launch gear, from the Zapnabber twins'' Zephyrium Capacitorium, which flings willing volunteers across the mountains, to a scientist who studies both time and sound. Razak''s Roughriders, hired to protect the scientists, man the defense guns against the ravagers that swarm the ridge. To the north, at the ridge''s southwestern edge, Bladespire ogres at the Bladespire Outpost raid the station''s power converters, and the gronn Maggoc, warden of the eastern mountains, prowls nearby.', 'warcraft.wiki.gg/wiki/Toshley''s_Station (left Sylvanaar over machines and experiments, built to experiment as they wish, Razak''s Roughriders); quest 10580 description; quest 10581 objective (up the ramp to the Razor Ridge); quests 10557, 10710 (Tally and Rally Zapnabber, Zephyrium Capacitorium); npc_text 10444 (Nickwinkle studies time and sound); npc_text 10469 and creature_text 21118 (assault by the bugs, def guns); quest 10620 description; quest 10584 description (Bladespire Outpost to the north raids power converters); quest 10843 (Bladespire Outpost at the southwestern edge of the Razor Ridge); quest 10996 description (Maggoc, warden of the eastern mountain range); DB: Maggoc 20600 stands in area 3922'),
(352207, 1, 3522, 7, 0, 8, 'Singing Ridge', 'The Singing Ridge is a field of great crystals in the south of the mountains, their shards humming with harmonies that one gnome scholar suspects are a sign of life, perhaps bound in some way to the nether drakes that nest there. The drakes are a strange inheritance. Their eggs were once black dragon eggs, changed by the wave of nether energy that washed over the land when Draenor blew apart. Dreadwing, their brood mother, dwells on the ridge, and crystal flayers scratch away at the shards. To the north, the Scalewing Shelf belongs to serpents whose breath crackles with lightning and to ridgespine stalkers that drop on passersby from the rocks.', 'quest 10594 reward text (crystals almost alive, symbiosis with the nether drakes); quest 10608 description; quest 10609 request text (eggs used to be black dragon eggs, changed when Draenor blew apart); quest 10853 description; quest 10845 description (Dreadwing, brood mother); quest 10657 description (Scalewing serpents, lightning breath); quest 10620 description (ridgespine stalkers)'),
(352208, 1, 3522, 8, 0, 8, 'Veil Vekh', 'In the southeastern canyons the Vekh''nir arakkoa keep Veil Vekh. For years they troubled no one, but something has stirred them: a strange religion holds them in a frenzy, and they now carry crystals that they charge at their spell circles for some dark purpose. Nearby, in the caverns of Trogma''s Claim, the Vekh''nir keep captured ogres as slaves under the watch of their leader, Vekh. Beside the veil, silkwing larvae spin their cocoons across Vekhaar Stand, prized by the Mok''Nathal for their silk and iridescent wings, and a tunnel from the stand leads into Death''s Door.', 'quest 10565 description and request text (benign for many years, now stirred; crystals infused at spell circles); quest 10566 (ogre slaves at Trogma''s Claim); quest 10846 description (Vekh''nir enslaved ogres at Trogma''s Claim, Vekh); quests 10617, 10618 (silkwing cocoons and wings); quest 10910 description (Vekhaar Stand, tunnel into Death''s Door); DB spawns: Silkwing Larva in 3827, Arakkoa Egg in 3783'),
(352209, 1, 3522, 9, 0, 8, 'Mok''Nathal Village', 'Mok''Nathal Village lies in the east of the mountains, where the Mok''Nathal still survive: a people of mixed orc and ogre blood, once honored by orc shamans before the clans fell to demonic corruption. Their hunters keep tame clefthoof and quilbeasts, the silk and wings of the canyon silkwings are worked into their crafts, and Matron Varah offers any wanderer a place at the village fires. The spiritcallers keep the memory of the ancestors alive in flame. Enemies press in from every side, from the Bladespire Outpost to the west, the Vekh''nir to the south and the nether drakes of the Singing Ridge, and the village chief, Leoroxx, measures every outsider by a harsh standard.', 'warcraft.wiki.gg/wiki/Blade''s_Edge_Mountains (Mok''Nathal honored by shamans before the demonic corruption, small village); DB spawns: Tame Clefthoof, Quilbeast, Mok''Nathal Hunter in 3844; quests 10617, 10618; npc_text 10249 (Matron Varah); npc_text 10647 (Dohgar: flame of their memory); quests 10843, 10845, 10846; npc_text 10645 (Leoroxx)'),
(352210, 1, 3522, 10, 0, 8, 'Death''s Door', 'Death''s Door is a canyon south of Mok''Nathal Village, reached through a tunnel from Vekhaar Stand, where the Burning Legion holds open a portal onto the world in which it breeds its hounds. Baelmon the Hound-Master maintains the ritual that keeps the portal alive at the canyon''s north end, and those who come through are sent on by translocator to Forge Camp: Wrath. Two warp-gates, one in the north and one in the south, serve to move and empower the void terrors, each within range of a fel cannon, while deathforge smiths and technicians tend the guns. To the druids of Evergrove it is the gravest danger the Legion poses in the mountains.', 'quest 10910 description (portal onto the world where the Legion breeds its hounds; route via Vekhaar Stand, south of Mok''Nathal); quest 10912 description (Baelmon maintains the ritual, north end); quest 10911 description (two warp-gates, teleportation and enhancement of void terrors, fel cannons); quest 10904 description; creature_text 19747 (translocator, Forge Camp Wrath awaits)'),
(352211, 1, 3522, 11, 0, 8, 'Razaan''s Landing', 'Razaan''s Landing, north of the Razor Ridge, is a camp of Razaani ethereals under Nexus-Prince Razaan. Their devices give off small pink orbs of light that drift above the landing like ornaments, and fiendling flesh beasts, some of them crackling with ether, wander among them. Scholars from Toshley''s Station are eager to study the ethereals and their technology, though the Roughriders have their doubts about the road north: a few of their people who headed that way have disappeared.', 'quest 10674 description (pink floating light orbs, probably only decoration); quest 10675 description (nether energy and souls, gnome souls; Nexus-Prince Razaan); quest 10671 description (fiendling flesh beasts, ether-energized flesh); quest 10859 description; quest 10865 description (some of them Mok''Nathal); quest 10620 request text (people who headed north disappeared)'),
(352212, 1, 3522, 12, 0, 8, 'Dragons'' End', 'Dragons'' End is a valley of old bones. Here the gronn and the Bladespire clan brought down the black dragons Deathwing had left on Draenor, and Gruul impaled their bodies on the spires, where the remains still hang. At the eastern edge lies the Cursed Hollow, lair of the gronn Grulloc, who guards a sack and a dragon skull from his father''s slaughter of the flight, and who cannot resist chasing a pig. Southwest of the Circle of Blood, the Churning Gulch seethes with crust bursters, among the most poisonous creatures in all of Outland, whose glands a certain alchemist values highly.', 'warcraft.wiki.gg/wiki/Gruul (Bladespire incantations, dragons impaled on the spires, bones at Dragons'' End); quest 10721 description (Cursed Hollow on the eastern edge of Dragons'' End, Huffer chased); quest 10800 description; quest 10995 description (dragon skull from his father''s slaying of the black dragonflight); creature_text 20216 (Me keep piggy as pet); quest 10715 description (Churning Gulch southwest, crust bursters most poisonous creatures); quest 10787 (deprecated) description (dragon corpses impaled upon the rocks at Dragons'' End); quest 10724 reward text (head of a black dragon from Dragons'' End)'),
(352213, 1, 3522, 13, 0, 8, 'Circle of Blood', 'The Circle of Blood is a great ogre structure in Daggermaw Canyon, raised around an arena where challengers meet one another in combat. Goblin organizers and merchants have set up their stalls at its gates. The towers just outside see quieter business. Atop the eastern one stands Mog''dorg the Wizened, an old Bloodmaul ogre who speaks with surprising clarity, and Chort, below, sends trusted visitors up to him with a warning to keep quiet. Nearby, a sharp-tongued alchemist who calls himself Baron Sablemane receives guests with a black whelp at his side.', 'warcraft.wiki.gg/wiki/Circle_of_Blood (large ogre structure holding the arena, in Daggermaw Canyon); DB spawns in 3775: Steamwheedle Sam <Arena Organizer>, arena vendors, Mog''dorg 22941, Chort 22995, Baron Sablemane 22103, Blackwhelp 22108; quest 11057 (tower on the eastern side of the arena); quest 10989 description; npc_text 10877 (Chort); npc_text 10860 (Mog''dorg''s clarity); quest 10783 description'),
(352214, 1, 3522, 14, 0, 8, 'Bloodmaul Camp', 'North of the Circle of Blood, Daggermaw Canyon runs on toward Gruul''s Lair, and along it the Bloodmaul have pitched Bloodmaul Camp. Here the clan plans its offensive against Sylvanaar and the Ruuan Weald under the chieftain Dorgok, and here its maulers, warlocks and battle worgs gather around kegs of grog, moonshine and seed beer. Down in the canyon, Bloodmaul taskmasters and soothsayers meet to talk in low voices, a den of marmots burrows among the rocks, and Bladespire enforcers patrol the stretch nearest the lair while Expedition wardens watch from the canyon''s edge.', 'quest 10795 description (attacks on Sylvanaar and Ruuan Weald staged from Bloodmaul Camp, Dorgok); quest 10784 / 10796 (maulers and warlocks); DB spawns: Bloodmaul Battle Worg, Green Spot Grog Keg, Ripe Moonshine Keg, Fermented Seed Beer Keg in 3777; quest 10720 description (marmot den in Daggermaw Canyon past the Circle of Blood); quest 10714 (taskmaster and soothsayer in conversation; sons of Gruul); DB spawns in 3826: Bladespire Enforcer, Expedition Warden'),
(352215, 1, 3522, 15, 0, 8, 'Gruul''s Lair', 'The road through Daggermaw Canyon ends at Gruul''s Lair, home of Gruul the Dragonkiller and of High King Maulgar, the old ogre king who serves him. Gruul trusts the approach only to the toughest of the Bladespire, enforcers, battlemages and ravagers led by Fingrom, and their encampment outside the lair holds the cage into which they threw Rexxar''s wyvern, Leokk. Before the entrance stands the altar of Goc, master of the Bladespire. On the right of the road, just short of the lair, lies Soulgrinder''s Barrow, where the gronn Skulloc Soulgrinder keeps himself hidden from the world.', 'quest 10805 description (Gruul protects the exterior with the toughest ogres, Fingrom); quest 10724 description (Leokk caged in the Bladespire encampment outside Gruul''s Lair); quest 10742 description (Goc''s altar outside Gruul''s Lair); quest 10806 description (Goc, master of the Bladespire); quest 11000 description and reward text (barrow on the right before Gruul''s Lair; Gruul and his puppet, the old king, Maulgar); quest 10998 description (Skulloc keeps himself hidden); DB spawns in 3774: Bladespire Enforcer, Battlemage, Ravager, Fingrom 20757, Leokk 22268, Meeting Stone'),
(352216, 1, 3522, 16, 0, 8, 'Evergrove', 'Evergrove is the Cenarion Expedition''s haven in the Ruuan Weald, kept almost entirely by night elves and open to Alliance and Horde alike. Tree Warden Chawn leads the druids'' effort to restore the balance of nature here, helped by scholars such as Timeon, who studies the arakkoa, and a gnome who wonders whether the druids hide batteries under their robes. The ancient Mosswood rests here before his long sleep. The weald around the grove is being cut and hunted bare by Wyrmcult hewers and poachers, the Ruuan''ok arakkoa raise their Harbingers of the Raven at Veil Ruuan to the north, and Watcher Moonshade holds the Wyrmskull Bridge to the west.', 'warcraft.wiki.gg/wiki/Evergrove (Cenarion outpost in Ruuan Weald, manned almost entirely by night elves, services to both factions, Chawn leader); npc_text 10534 (Chawn: reestablish the balance of nature); quest 10615 reward text (Timeon); npc_text 10554 (O''Mally: batteries under those robes); npc_text 10640 (Mosswood: soon I will plant roots and sleep); quests 10682, 10713, 10717 (hewers, poachers); quest 10567 description (Ruuan''ok Harbingers of the Raven); npc_text 10667 and quest 10894 (Watcher Moonshade at Wyrmskull Bridge)'),
(352217, 1, 3522, 17, 0, 8, 'Forge Camp: Anger', 'On the eastern heights the Burning Legion works Forge Camp: Anger, where doomforge engineers and attendants labor at fel cannons under the eye of anger guards and a ring of Legion obelisks. Its masters take their orders through a Legion communicator from a demon who does not like to be disturbed. Just north of the camp, fel corrupters spread their taint through the Bladed Gulch, turning its scalewings and daggermaws into felsworn beasts. Farther north lies Skald, a scorched land of ash and searing elementals. A great wood flourished there until the Legion sent imps of flame to burn it away, and Mosswood the Ancient is the last of its people.', 'quest 10819 description (east of Evergrove, Legion communicator); quests 10820, 10821 (Doomforge attendants and engineers, Doomcryer undermining his authority, five obelisks, anger guards); DB spawns in 3787: Legion Fel Cannon, Anger Guard, Legion Obelisk; quest 10753 description (corruption spreading across Bladed Gulch, Fel Corrupters, Felsworn); quest 10770 description (great wood burned by imps sent by the Legion); quest 10771 description (only I remain); DB spawns in 3866: Searing Elemental, Scorch Imp, Fertile Volcanic Soil'),
(352218, 1, 3522, 18, 0, 8, 'Blackwing Coven', 'The Blackwing Coven is the cavernous stronghold of the Wyrmcult, at the end of the road that runs west past Grishnath and the Raven''s Wood. Its humans, orcs, draenei and Broken seek the power of the surviving black dragons, and in its depths they raise blackwhelps among clutches of eggs. Their patriarch is Maxnar the Ashmaw, one of the dragonkin. The cult''s fighters mass in the Wyrmskull Tunnel under Draaca Longtail, while the watchers of Evergrove make their stand at its far end.', 'warcraft.wiki.gg/wiki/Wyrmcult (humans, orcs, Broken and draenei; harness the power of the black dragonflight; Blackwing Coven); quest 10722 and 10747 descriptions (route, whelps and eggs); quest 10748 description (Maxnar, dragonkin); creature_text 21983 (Kolphis second-in-command); npc_text 10541, 10543 (Kolphis: lumber and livestock, war with Boulder''mok, truce with the arakkoa); quest 10893 description (wyrmcultists massing in the tunnel, Draaca Longtail); creature_template 21389 subname Wyrmcult Patriarch; DB positions: Maxnar, Kolphis and the coven''s whelps and zealots stand at z 150 to 178, some 200 yards below the Forge Camp: Wrath demons (z 364 to 374); npc_text 10667 (Moonshade: we''ll make our stand here)'),
(352219, 1, 3522, 19, 0, 8, 'Raven''s Wood', 'The Raven''s Wood spreads across the northwest, a forest of leafbeards and stonebarks watched over by Treebole, an ancient of lore who stands at a fork in the path past Grishnath. An evil has crept into its trees: the leafbeards and stonebarks have turned on all who pass, and dire ravens wheel through the branches. On the wood''s western side lies Boulder''mok, a camp of Bladespire ogres who bring sacrifices to the altar of Gorgrom the Dragon-Eater and who fight a running war with the Wyrmcult nearby.', 'quest 10829 description (Treebole, ancient of lore, fork in the path past Grishnath); quest 10830 description (Grishna, koi-koi spirits, leafbeards and stonebarks); DB spawns in 3830: Dire Raven, Raven''s Wood Leafbeard and Stonebark; quest 10803 description (west side of the Raven''s Wood); quest 10786 (Bladespire ogres of Boulder''mok); quest 10723 description (Gorgrom accepting sacrifices from the ogres of Boulder''mok); npc_text 10543 (Wyrmcult fighting the Boulder''mok ogres)'),
(352220, 1, 3522, 20, 0, 8, 'Grishnath', 'Grishnath is the roost of the Grishna arakkoa, in the north beside the Raven''s Wood. Totems left by their Oracles of the Raven stand at four shrines, and through them the faithful hear the Word of the Raven, spoken in a tongue that outsiders cannot understand. The Grishna carry strange orbs beneath their feathers, suffused with a purple glow and pulsing to an unheard beat, and holding one leaves a traveler uneasy. The Cenarion Expedition at Evergrove watches the cult with growing concern.', 'quest 10607 description (totems of the Oracles of the Raven, the Word of the Raven); broadcast_text 19475, 19476, 19477, 19478 (prophecies); DB: First to Fourth Prophecy objects in 3781; quest 10825 description (orb from beneath the contour feathers); quest 10830 description (Grishnath orbs found throughout Grishnath; Grishna possess the trees); quest 10615 description (the Cenarion Expedition concerned with the arakkoa''s intentions)'),
(352221, 1, 3522, 21, 0, 8, 'Ogri''la', 'High on a western terrace, reached only by flight, lies Ogri''la, the ogre heaven that the clans below whisper about. Its ogres, many of them two-headed, have gained a keen mind from the crystals that grow around their home, and they want only to live in peace, which the demons of the forge camps, the ethereals and above all the black dragonflight will not allow. Chu''a''lor, whose two heads finish each other''s sentences, greets newcomers. Just to the north, the Sha''tari Skyguard keeps its outpost under Sky Commander Keller, who wears an eyepatch and claims he built the place with his own hands, and flies missions from it for the protection of both.', 'warcraft.wiki.gg/wiki/Ogri''la (ogres transcended through apexis crystals, aided by the Sha''tari Skyguard); npc_text 10926 (Chu''a''lor: crystals, peace, demons, ethereals, Black Dragonflight); quest 11025 reward text (left and right heads); npc_text 10919 (Kronk: you only have one head); quest 11009 description (Ogri''la in the heavens above); quest 11030 and 11010 descriptions (flying mount); quest 11062 description and reward text (Skyguard Outpost to the north, built with me own hands, missions for mutual protection); npc_text 10906 (Keller''s eyepatch)'),
(352222, 1, 3522, 22, 0, 8, 'Vortex Pinnacle', 'Vortex Pinnacle crowns the western terrace around Ogri''la, a field of crystal formations among the relics of the Apexis, a vanished sect of arakkoa who once lived atop these mountains. Their relics still answer those who master their sequences of colored light, and gan''arg analyzers of the Legion pick over them for secrets. Aether rays drift overhead, coveted by the Skyguard as mounts. The ghost of an arakkoa elder, Sai''kkal, lingers here, his sight so dim that he peers at every visitor as though hoping to know them. The black dragons Rivendark and Obsidia rule the skies of this terrace from their perches, a constant menace to Ogri''la.', 'quest 11058 description (Apexis, extinct sect, relics with colored sequences); quest 11025 request text; DB spawns in 3832: Apexis Relic, Apexis Monument, Gan''arg Analyzer, Aether Ray; quest 11065 description (aether rays around Vortex Pinnacle as remounts); quest 11078 description (Rivendark and Obsidia lord over this terrace, perches); npc_text 10794 (Sai''kkal cannot see clearly; default gossip); DB displays: Rivendark 24139 and Obsidia 12869 use black dragon skins; npc_text 10926 (the Black Dragonflight threatens Ogri''la)'),
(352223, 1, 3522, 23, 0, 8, 'Forge Camps Wrath and Terror', 'Two Burning Legion forge camps flank the western terrace, Forge Camp: Wrath to the north and Forge Camp: Terror to the south. Their flak cannons, fed from stacks of fel cannonballs, shoot down Skyguard riders left and right, and in each camp a fel crystalforge pours out green smoke as it turns apexis shards into unstable flasks. Demon chieftains such as Galvanoth and Braxxus answer when shards are offered at the camps'' burning fel crystal prisms. On the southern border of Wrath the demons have raised Shartuul''s Transporter, an experimental gate meant to expand the camp, which the ogres of Ogri''la fear will soon crush them.', 'quest 11010 description (Wrath and Terror to the north and south, fel cannons shooting down the Skyguard); DB spawns in 3785: Legion Flak Cannon, Fel Cannonball Stack; quest 11030 description (fel crystalforge at either forge camp, green smoke, ten apexis shards); quest 11079 description (demon chiefs at fel crystal prisms: Galvanoth, Braxxus, Zarcsin, Mo''arg Incinerator); quest 11026 reward text (special transporter on their southern border, experimental gate to expand the forge camp); quest 11060 request text (the camp growing bigger, soon too big and crush us)'),
(352224, 1, 3522, 24, 0, 8, 'Bash''ir Landing', 'The northernmost shelf of the mountains holds Bash''ir Landing, a settlement of the Ethereum named for Bash''ir and his followers. Here they keep great stasis chambers, far larger than the prisons the Ethereum use elsewhere. A crystalforge stands at the landing''s northeast corner, and every few hours Skyguard aether-techs fly in to raid it. East of the landing rises the Crystal Spine, where felstorm corruptors and infernals of the Legion roam among Apexis relics, and the black dragons Insidion and Furywing rule the skies from their perches.', 'quest 10974 description (Ethereum settlement on the northernmost shelf); warcraft.wiki.gg/wiki/Bash''ir_Landing (named for Bash''ir and his subdivision of the Ethereum; Skyguard assaults every two hours); quest 10974 reward text (beasts from many worlds, hope to command them); quest 11513 description (ethereals smuggling mana cells out of Tempest Keep for Kael''thas); quest 11061 description (crystalforge at the northeast corner); quest 11119 description; DB spawns in 3865: Felstorm Corruptor, Darkflame Infernal, Apexis Relic; quest 11078 description (Insidion and Furywing rule the terrace to the northeast); DB displays: Insidion and Furywing 12869, black dragon skins; AreaTable 3864 name Bash''ir Landing (wiki trivia: the non-possessive form is correct)'),
(352230, 2, 3522, 1, 2, 8, 'Rexxar', 'Rexxar, Champion of the Horde, is Mok''Nathal, of mixed orc and ogre blood. He made his name on Azeroth, roaming the wilds with his bear Misha, and once took Thrall''s place at a summit that proved to be an ambush. Now he has crossed the Dark Portal, chasing rumors of his people across Outland. At Thunderlord Stronghold that search weighs on him alongside the struggle against the Alliance and the war with the ogres and their gronn masters, and even he admits he can use some help. Beside Misha he keeps his hawk Spirit and his boar Huffer, and a wyvern, Leokk, whom the Bladespire took captive soon after he came to the mountains.', 'quest 10709 description and reward text (my son; left thirty years ago to follow the Horde to Azeroth); quest 10614 description (rumors across Outland); npc_text 10661 (Rexxar); warcraft.wiki.gg/wiki/Thunderlord_Stronghold (Rexxar came seeking his race); quests 10714, 10721, 10723 (Spirit, Huffer, Misha); quest 10724 (Leokk); quest 10742 reward text (true son); warcraft.wiki.gg/wiki/Rexxar (Warcraft III: The Frozen Throne, 2003: volunteered to go to the summit in Thrall''s place; bear Misha); warcraft.wiki.gg/wiki/Razor_Hill (the Kul Tiran summit was a planned ambush; Rexxar went in Thrall''s place and defeated the assassins)'),
(352231, 2, 3522, 2, 2, 8, 'Leoroxx', 'Leoroxx leads the Mok''Nathal of the eastern village, and he judges outsiders as harshly as his own. Enemies surround his people, and he would give them a better life if those enemies allowed it. Those who come to the Mok''Nathal, he says, understand neither them nor their struggle to survive, and the only way to understand is to share in it. So he sends would-be friends against the foes who press on the village, beginning with Vekh, leader of the Vekh''nir arakkoa, in the caverns of Trogma''s Claim.', 'quest 10709 description; quest 10709 reward text (Leoroxx staunchly against his leaving); warcraft.wiki.gg/wiki/Leoroxx; quests 10846, 10843, 10845 descriptions and reward texts'),
(352232, 2, 3522, 3, 0, 8, 'Baron Sablemane', 'Baron Sablemane waits outside the Circle of Blood, a master of the alchemical arts whose loathing of interruptions is surpassed only by his hatred of Gruul the Dragonkiller and his seven sons. He will help those who fight the gronn, but always for a price, because, as he puts it, free things destroy friendships. He brews poisons from crust burster venom, a black whelp keeps him company, and his agent Samia Inkling aids the druids of Evergrove against the Wyrmcult at his behest.', 'npc_text 10603 (Sablemane gossip); quest 10783 description (master of the alchemical arts); quest 10715 description (free things destroy friendships); quests 10785, 10801 (they slaughtered my people, my children; dragon fire trap); quest 10818 description (pet dragon); npc_text 10538 (Samia, at the behest of her master Baron Sablemane); quest 10806 reward text (transformation, true identity); warcraft.wiki.gg/wiki/Baron_Sablemane (human disguise of a black dragon); DB: Baron Sablemane 22103 uses human male display 20807; his battle form Sabellian 22496 uses display 21079 with black dragon skins'),
(352233, 2, 3522, 4, 0, 8, 'Gruul the Dragonkiller', 'Gruul the Dragonkiller is the greatest of the gronn and the master of the Blade''s Edge Mountains, worshiped as a god by the ogres who live there. When Deathwing''s black dragons nested in these lands, Gruul led the gronn and ogres against them; the Bladespire tore the dragons from the sky with their incantations, and Gruul impaled the bodies on the spires of Dragons'' End. The ogre clans now fight one another for his favor, which rests with the Bladespire, and his seven sons enforce his will across the mountains and as far as Nagrand. He keeps to his lair in the north beside Maulgar, the ogres'' aging High King, whom his enemies call Gruul''s puppet.', 'warcraft.wiki.gg/wiki/Gruul (war on the black dragonflight, Bladespire incantations, impaled on the spires, worshiped by the ogres of Blade''s Edge, seven sons); quests 10504, 10505 descriptions and request texts (clans vie for the favor of Gruul the Dragonkiller); nagrand.json 351831 (Durn in Nagrand); quest 11000 reward text (Gruul and his puppet, the old king, Maulgar)'),
(352234, 2, 3522, 5, 0, 8, 'The Sons of Gruul', 'Gruul has seven sons, gronn who share their father''s rule over the mountains and the ogres who live in them. Goc is master of the Bladespire, with an altar outside his father''s lair. Gorgrom the Dragon-Eater accepts sacrifices from the ogres of Boulder''mok. Grulloc, dim-witted, hatches his schemes in the Cursed Hollow, and Maggoc patrols the eastern ranges as their warden. Skulloc Soulgrinder, trained by the ogre warlock Vim''gol the Vile, hides in a barrow near the lair. Slaag went into exile among the Gordunni ogres above Shattrath, and Durn the Hungerer hunts the fields of Nagrand. Mog''dorg the Wizened believes no ogre will be free until all of them are dead.', 'warcraft.wiki.gg/wiki/Gruul (seven sons named); quests 10742, 10806 (Goc, master of the Bladespire, altar outside Gruul''s Lair); quests 10723, 10798 (Gorgrom at Boulder''mok, behind the Bloodmaul plans); quests 10721, 10995 (Grulloc); quest 10996 (Maggoc, warden of the eastern range); quest 10998 (Skulloc trained by Vim''gol); quest 10997 (Slaag exiled among the Gordunni); nagrand.json 351831 (Durn); quest 11000 reward text; quests 10742, 10806 RequiredNpcOrGo 20555 (Goc summoned at his altar, Horde and Alliance); quests 10723, 10802 (Gorgrom summoned at his altar, Horde and Alliance); quest 11000 (Skulloc forced out at the barrow, open to all)'),
(352235, 2, 3522, 6, 0, 8, 'Mog''dorg the Wizened', 'Mog''dorg the Wizened is a Bloodmaul ogre who stands atop a tower outside the Circle of Blood and speaks with a clarity no other ogre below can match. He has built a secret society, an underground resistance against the gronn, for he believes his clan faces annihilation at the hands of the Bladespire and the sons of Gruul who back them. He sent the ogre Grok to Shattrath to beg for help, and dreams of a home where ogres may decide their own destiny. Not all ogres trust him: the wandering speaker Mar''grom calls Ogri''la a myth and Mog''dorg''s words lies.', 'npc_text 10800, 10860 (resistance; staff from Ogri''la); quest 10983 description and reward text (sent Grok to the city); quests 10989, 11057 reward texts; quest 10996 reward text (home for the ogres, own destiny); creature_text 18693 (Speaker Mar''grom)'),
(352236, 2, 3522, 7, 1, 8, 'Toshley', 'Toshley is the gnome inventor who brought a whole band of scientists to Outland, with Razak''s Roughriders hired to guard them. They first settled with the night elves at Sylvanaar, but their machines and experiments made a mess of the Living Grove, and the elves sent them away, which Toshley counts a blessing. He left a remote sentry, R-3D0, on the Jagged Ridge to turn visitors away, along with a trail of spare parts leading straight to his door. At his station he runs hair-raising projects, capturing electromentals and charging spheres with lightning from wild serpents, and cheerfully tells volunteers the odds that they would implode.', 'quest 10580 description (driving Toshley and his gnome friends away); npc_text 10423 (glad to be rid of those stuffy elves); quest 10620 description (hired on to help Toshley when he decided to move to Outland); quests 10580 reward and 10581 description (R-3D0, trail of spare parts); quest 10584 description (electromentals); quest 10657 description and reward text (lightning, 23.72 chance of imploding)'),
(352237, 2, 3522, 8, 0, 8, 'Tree Warden Chawn', 'Tree Warden Chawn, a tauren of the Cenarion Expedition, leads Evergrove. He came to the Ruuan Weald to restore the balance of nature to the mountains and finds the arakkoa and the Wyrmcult making that task hard. Chawn prefers to begin with talk: when the cultists began logging and poaching in the weald, his first answer was to seek out their overseer and offer a compromise. He is quick to sense evil in an object, freely admits he is no military planner, and gladly accepts help, whether from passing travelers or from the scholar Samia Inkling.', 'warcraft.wiki.gg/wiki/Evergrove (Tree Warden Chawn, tauren, leader); npc_text 10534; quest 10682 description and reward text; quest 10713 description; quest 10825 request and reward texts (senses evil); quest 10894 description (not much of a military planner)'),
(352238, 2, 3522, 9, 2, 8, 'T''chali the Witch Doctor', 'T''chali the Witch Doctor is a troll who came down into Bloodmaul Ravine to teach the ogres how to brew their beer. He used to be a friendly sort, he says, but once the lesson was learned the Bloodmaul buried him in the ravine and left him there to rot, and worst of all, they stole his hookah. T''chali still speaks from his grave, and he wants his hookah back, along with some of the brew he taught them to make. The ogres who took the pipe, he thinks, went off southwest toward the mine.', 'quest 10542 description; quest 10545 description (perfect brew, strengthens you and weakens your enemy); quest 10543 description (Grimnok led the burial, Korgaah came south to raid); quest 10543 reward text and 10544 description (powerful witch doctor in life, revenge not quenched)'),
(352250, 3, 3522, 1, 2, 8, 'Rexxar''s Kin', 'Among the Bladespire, Horde fighters find a Thunderlord clan artifact and bring it to Rokgah Bloodgrip, a scholar of that fallen clan at Thunderlord Stronghold. He has read all of the clan''s texts and seeks a drum, an arrow and a tablet lost when the Horde crushed the Bladespire and drove them back into their hold, though others have gone after them and failed, or worse. The relics matter: once all are recovered, he says, the Horde''s right to the stronghold will be secured by appeasing its restless dead. With the three in hand, he gives a fiery fragment of his own soul to send a seeker''s spirit after the last relic.', 'quests 10524, 10525, 10526 (descriptions and reward texts); npc_text 10322 (Rokgah); quest 10718 description and reward text (Garm, last chieftain of the Thunderlord); quest 10614 description; quest 10709 description and reward text; quest 10714 description and reward text; warcraft.wiki.gg/wiki/Garm_Wolfbrother'),
(352251, 3, 3522, 2, 0, 8, 'Baron Sablemane''s Price', 'Baron Sablemane, the master alchemist at the Circle of Blood, will help anyone against the gronn, always for a price. Rexxar of Thunderlord Stronghold, set on ending the Bloodmaul threat to the Mok''Nathal, sends for his help: he wants a poison for the Bloodmaul kegs, to be carried into their camp by a marmot, and the baron''s work begins with venom glands from the crust bursters of the Churning Gulch. For the Alliance the trail begins elsewhere, with Commander Haephus Stonewall, Sylvanaar''s envoy at Evergrove, and Dorgok of Bloodmaul Camp, whose clan is preparing an offensive against Sylvanaar and the Ruuan Weald, though no one yet knows who is pushing them to it.', 'quests 10783, 10715, 10749, 10720, 10721, 10785, 10723, 10724, 10742 (Horde); quests 10795, 10797, 10798, 10799, 10800, 10801, 10802, 10818, 10805, 10806 (Alliance); npc_text 10612 (Stonewall representing Sylvanaar at Evergrove)'),
(352252, 3, 3522, 3, 0, 8, 'The King of the Ogres', 'Mog''dorg the Wizened leads a secret resistance among the Bloodmaul, convinced his clan will be wiped out by the Bladespire and the gronn behind them. Those he trusts are sent against the gronn one by one: Grulloc in the Cursed Hollow, for the dragon skull he treasures from Gruul''s slaughter of the black dragonflight; Maggoc on the Razor Ridge, for the treasure chest he carries everywhere; and even Slaag, who exiled himself among the Gordunni ogres above Shattrath, lest he return once his brothers are dead.', 'quests 10989, 11057 reward texts; quest 10995 description and reward text; quest 10996 description and reward text; quest 10997 description; quest 10998 description; quest 11000 description and reward text; quest 11009 description; creature_text 22941 (All hail the new king)'),
(352253, 3, 3522, 4, 0, 8, 'Ogre Heaven', 'Ogri''la''s ogres are newly wise and wish only for peace, but enemies beset them on every side. Chu''a''lor teaches visitors about the Apexis shards every creature on the terraces covets, named for a vanished arakkoa civilization, and the relics that reward those who master their sequences of light, while the larger monuments summon crystal guardians that long ago turned on their arakkoan makers. The weary father Torkus has ten sons, all longing to join the Sha''tari Skyguard. At the outpost nearby, Sky Commander Keller and his sharp-tongued sergeant Vanderlip send riders to bomb the forge camps'' fel cannonball stacks, Skyguard Khatie wants aether rays roped as remounts, and the terraces'' dragons must be lured from their perches by breaking their eggs. Kronk''s banishing crystal sends slain demons back whence they came, and Gahk dreams of smashing the demons'' transporter.', 'quest 11025 description and request text; quests 11058, 11059; quests 11030, 11061 descriptions, npc_text 10916 (ten sons); quest 11062 reward text (Vanderlip''s sharp tongue); quests 11010, 11102; quests 11065, 11066; quest 11078 description; quest 11026 description and reward text; npc_text 10923 (Gahk)'),
(352254, 3, 3522, 5, 0, 8, 'The Souls of Razaan''s Landing', 'Gnomes from Toshley''s Station have been vanishing on the road north, and at Mok''Nathal Village the spiritcaller Dohgar senses a great deal of pain coming from the ethereals'' direction. Both turn their eyes to the small pink orbs that drift above Razaan''s Landing. Toshley, curious about the Razaani''s technology and sure the orbs are only decoration, sends a trap to catch a few. Dohgar, who has already set free the twisted spirits of the Singing Ridge''s nether drakes and thinks the orbs look like souls, plants totems to draw them in.', 'quests 10620, 10671 (missing people); quests 10674, 10675 (Toshley); quests 10853 reward text, 10859, 10865, 10867 (Dohgar and Leoroxx)'),
(352255, 3, 3522, 6, 0, 8, 'Brew and Banner', 'Every ogre clan in Blade''s Edge fights the others for Gruul''s favor, and the newcomers have learned to use the feud. At Sylvanaar the dwarf Borgrim Stouthammer, on holiday with the Explorers'' League after the dirt and insects of Silithus, sends for Bloodmaul brew, since the elves know nothing of fermentation. Vindicator Vuuleen sits caged by choice inside Bladespire Hold to spy on the clan, but wants back the sword and shield its leaders took from him. The Horde''s guide in the feud is a dead troll: T''chali, buried by the Bloodmaul he taught to brew, wants his hookah and his brews back.', 'quests 10504, 10505 request texts (clans vie for Gruul''s favor); quests 10510 request text, 10511, 10512 (Stouthammers, vacation, Silithus); quests 10516, 10517, 10518; quests 10542, 10545, 10543, 10544'),
(352256, 3, 3522, 7, 0, 8, 'The Blackwing Coven', 'When the Wyrmcult began felling the trees of the Ruuan Weald and slaughtering its wildlife, Tree Warden Chawn sent an envoy to their overseer, Nuaar, who patrols between the cult''s camps, offering compromise but refusing to allow wholesale slaughter. Until lately the cultists kept to the Blackwing Coven through the tunnel to the west; now they are encroaching on Evergrove. A bloodstained note dropped by one of them, meant for Nuaar and signed by one Kolphis Darkscale, may tell more.', 'quests 10682, 10713; npc_text 10533 (Nuaar: no negotiations); quests 10719, 10894, 10893, 10722; npc_text 10541, 10542, 10543 (Kolphis meeting); creature_text 21983 (second-in-command); quests 10717, 10747, 10748'),
(352257, 3, 3522, 8, 0, 8, 'Whispers of the Raven', 'The arakkoa of Blade''s Edge were long a quiet people, but something has stirred them, and every power in the mountains wants to know why. Dertrok of the Mok''Nathal studies the crystals the Vekh''nir charge at their spell circles, tests their power on the ogre slaves of Trogma''s Claim, and sends his findings to Timeon at Evergrove. At Sylvanaar, Daranelle wants a visitor to cast a Lashh''an feather spell so she can learn its nature. Timeon wants a pendant from the Harbingers of the Raven, heralds of the Ruuan''ok, so that the speech of the Grishna can be understood at their four shrines, and strange orbs taken from the Grishna find their way to Tree Warden Chawn.', 'quests 10565, 10566, 10615 (Dertrok, Horde); quests 10555, 10556 (Daranelle, Alliance); quests 10567, 10607 (Timeon; peaceful for a long time, misfits and madmen); broadcast_text 19475; quests 10825, 10829, 10830'),
(352258, 3, 3522, 9, 0, 8, 'The Hounds of Death''s Door', 'The Burning Legion presses on the Ruuan Weald from the east. Fel corrupters spread its taint across the Bladed Gulch, turning the scalewings and daggermaws there into felsworn beasts, and the druids of Evergrove, who grieve to destroy what Elune has made, send help against them. From the corrupters'' bodies comes a damaged mask that still murmurs with strange sounds, as if voices were speaking inside it. If it were whole, they might be heard more clearly, and O''Mally Zapnabber at Evergrove might be the one to mend it.', 'quests 10810, 10812, 10819, 10820, 10821; quests 10910, 10904, 10911, 10912; item 31384 Damaged Mask dropped by Fel Corrupter 21300; quest 10753 description and reward text (Bladed Gulch corruption, Faradrella of Evergrove)'),
(352259, 3, 3522, 10, 0, 8, 'The Stasis Chambers of Bash''ir', 'Great stasis chambers stand at Bash''ir Landing, much larger cousins of the Ethereum''s prisons elsewhere, and an image of Commander Ameer of the Protectorate waits among them to learn what they hold. The Sha''tari Skyguard has its own business at the landing. Every couple of hours Sky Commander Keller''s aether-techs launch an assault on the landing''s crystalforge, which they prefer to call research, and those who keep the ethereals off them long enough may buy the surplus the crystalforge yields.', 'quest 10974 description and reward text; quest 10975 request and reward text; quest 10976 description; quest 10977 description; quest 11119 description and reward text; netherstorm.json 352340 (the trail leads to Bash''ir''s Landing)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(352202, 1, 0, 255, 'Daranelle of Sylvanaar had a visitor gather plucked feathers and cast one of the tome''s spells at a Lashh''an circle. Its pictograms showed an arakkoa suffused with the spirit of a kaliri, and the spell proved to be neither a curse nor a conjuring, but a strange kind of communion that fills the caster with a kaliri''s spirit. What it is meant for, she cannot yet say.', 'quest 10555 reward text and 10556 description (pictogram, kaliri spirit); quest 10556 reward text (communion or communication spell, not sure what to make of it)'),
(352203, 1, 0, 255, 'The mine hides plunder as well. Rokgah Bloodgrip of Thunderlord Stronghold, guided by a seeker''s vision, learned that the Thunderspike, a lost Thunderlord spear, lies in the deepest reaches of the Draenethyst Mine, where the Bloodmaul keep it, most likely taken from the Bladespire who once held the stronghold and its relics.', 'quest 10525 reward text (back of the Draenethyst Mine, stolen from the Bladespire); quest 10524 description (the Bladespire inhabited the stronghold)'),
(352204, 1, 0, 255, 'Help has been asked of the stronghold, too. Shadow Hunter Denjai of Zabra''jin sent word from Zangarmarsh begging aid against the ogres spreading through the marsh. Nekthar answered that the stronghold is spread thin with ogre troubles of its own, but promised to pass on what it knows of the local tribes and their tactics, in the hope that, if Zabra''jin holds out long enough, the two might one day strike the ogres from both sides.', 'quest 9795 description and reward text (Nekthar''s answer to Denjai)'),
(352211, 1, 0, 255, 'The orbs are no ornaments. Those who gathered them for study found them made of nether energy bound together with captured souls, and the neighbors who examined them recognized some of those souls as their own people''s.', 'quest 10675 description (nether energy and souls, gnome souls); quest 10865 description (souls, some of them Mok''Nathal)'),
(352214, 1, 0, 255, 'The Bloodmaul do not plan their offensive alone. A son of Gruul stands behind the clan and pushes its warriors against their neighbors, so that whatever is plotted around the camp''s kegs, the will behind it belongs to a gronn.', 'quest 10714 reward text (the sons of Gruul command the Bloodmaul); quest 10798 description (Gorgrom behind the Bloodmaul plans against Sylvanaar)'),
(352217, 1, 0, 255, 'Those who have spoken through the communicator have heard the demon at the far end rage that his minions would never dare undermine his authority, and then name the one he suspects of doing just that: Doomcryer, who has been working against him for some time and whose anger guards hold the keys to summon her.', 'quest 10820 description and reward text; quest 10821 description (Doomcryer undermining his authority, keys held by the anger guards)'),
(352218, 1, 0, 255, 'Below Maxnar stands Kolphis Darkscale, the cult''s second in command, and those who have heard him speak freely know more. He presses his overseers for the weald''s lumber and livestock, for the cult must prove itself worthy of elevation within the ranks of the Blackwing. Already at war with the Boulder''mok ogres, it can afford no second front, so Kolphis has secured a temporary peace with the arakkoa, while Maxnar readies an all-out assault to wipe the druids out.', 'npc_text 10541, 10542, 10543 (Kolphis at the meeting: lumber and livestock, elevation within the ranks of the Blackwing, Boulder''mok, truce, Maxnar''s attack); quest 10722 reward text; creature_text 21983 (Samia: second-in-command; said after the note, DONE 10719)'),
(352219, 1, 0, 255, 'The evil has a source. The Grishna arakkoa of nearby Grishnath have caused evil koi-koi spirits to possess the leafbeards and stonebarks, and unless the trees are saved, the whole of the Raven''s Wood will be lost.', 'quest 10830 description (Grishna, koi-koi spirits, leafbeards and stonebarks)'),
(352220, 1, 0, 255, 'Those who have borrowed a Grishna''s understanding and listened at the shrines have heard the prophecies: the raven will rise again from the darkest night, the faithful will take flight with it while the rest walk the ground in shame, the dark wings will consume the minds of the weak, and the old blood will flow once more.', 'quest 10607 description; broadcast_text 19475, 19476, 19477 (prophecies)'),
(352220, 2, 0, 255, 'The orbs are more than tokens of faith. One carried to Evergrove held a residual memory of the evil within it, and it showed that the Grishna use such magic to set evil spirits upon the ancients and protectors of the neighboring Raven''s Wood.', 'quest 10825 reward text (residual memory); quest 10829 description (the arakkoa cause the ancients and protectors to be possessed)'),
(352224, 1, 0, 255, 'The chambers are no ordinary prisons. Evidence brought out of Stasis Chamber Alpha showed what they truly hold: savage beasts and creatures of many, many worlds, which the Ethereum hope to bend to their bidding one day.', 'quest 10974 description (larger versions of the prisons, called stasis chambers); quest 10974 reward text'),
(352224, 2, 12, 255, 'The Shattered Sun Offensive has learned that the ethereals of the landing serve another cause as well. They had been smuggling mana cells out of Tempest Keep and carrying them to the Sunwell for Kael''thas, hidden from plain sight and guarded by phase wyrms.', 'quest 11513 description (smuggling mana cells out of Tempest Keep to the Sunwell for Kael''thas, phase devices, phase wyrm guardians)'),
(352230, 1, 0, 255, 'Rexxar is the son of Leoroxx, chief of the Mok''Nathal. Thirty years ago he left his people to follow the Horde to Azeroth, though his father was staunchly against it, and Leoroxx has neither forgiven him nor welcomed him home. Rexxar had hoped the years would dull that anger. His father wanted a Mok''Nathal for a son, and Rexxar means to open his eyes to the one he has.', 'quest 10709 description and reward text'),
(352230, 2, 0, 255, 'With Gorgrom and Goc dead, the Bloodmaul and Bladespire threaten the Mok''Nathal no longer, and Rexxar faced Goc himself at the gronn''s altar. Even so, he is not ready to face his people. There is still much he can learn and do to grow stronger, he says, and to show his father that he is his true son.', 'quest 10742 description, request and reward texts'),
(352231, 1, 0, 255, 'Leoroxx is father to Rexxar, though he will not call him one of his people. Rexxar made his choice a lifetime ago, and to Leoroxx he is not welcome: the Mok''Nathal have troubles enough with the Bloodmaul, and being born a half-breed, he says, does not make one Mok''Nathal.', 'quest 10709 description'),
(352231, 2, 0, 255, 'After Vekh came Gnosh Brognat, leader of the Bladespire Outpost, and then Dreadwing, brood mother of the Singing Ridge''s nether drakes. Even with the chiefs of all three threats dead, Leoroxx offers only a grudging token and a warning: those who did it still do not fully understand what it is to be Mok''Nathal.', 'quests 10843, 10845 descriptions and reward texts'),
(352232, 1, 0, 255, 'His hatred is personal. The gronn, he says, slaughtered his people and his children, and he means to have his revenge. The trap he made to that end is drawn from the very essence of dragon fire, and those who carried it home were left wondering how an alchemist comes by such rare substances.', 'quests 10785, 10801 descriptions (they slaughtered my people, my children; dragon fire trap); quests 10785, 10801 reward texts (rarified substances)'),
(352232, 2, 0, 255, 'In time the baron sent his pet dragon with a summons and took a hand himself. At Goc''s altar outside Gruul''s Lair he answered the call of his signet and joined the fight against the son of Gruul, and in the battle he shed his human guise: Baron Sablemane is a black dragon. Afterward he asked that his true identity be kept quiet, for now.', 'quest 10818 description (pet dragon); quest 10806 description and reward text (transformation, true identity); DB: battle form Sabellian 22496 uses black dragon display 21079'),
(352234, 1, 0, 255, 'The sons are the true power behind the ogre wars of Blade''s Edge. Gorgrom the Dragon-Eater is master of the Bloodmaul as well, quietly driving them against their neighbors while the Bladespire, Gruul''s favorites, answer to Goc.', 'quest 10798 description (Gorgrom behind the Bloodmaul plans); quest 10723 reward text (the ogres of Bloodmaul and their master, Gorgrom)'),
(352235, 1, 0, 255, 'His clarity is a gift of Ogri''la. The ogres there gave him a staff whose crystal sharpened his mind, and with the sons of Gruul dead he hopes one day to bring that boon to all his brethren. Reuniting the clans will take time, he admits, for old grudges are difficult to overcome.', 'npc_text 10860 (staff from Ogri''la; shown only after quest 11000 is rewarded, gossip condition); quest 11009 description (reunifying the clans, old grudges)'),
(352237, 1, 0, 255, 'The overseer dismissed his proposals out of hand. Only then did Chawn set his allies on the cult''s hewers, for if the Wyrmcult would not listen to reason, he said, perhaps it would listen to a more assertive kind of persuasion. The trees, he decided, must come first.', 'quest 10682 reward text; quest 10713 description (offered on the 10682 turn-in)'),
(352238, 1, 0, 255, 'T''chali had not told the whole story. The Bloodmaul were in dire straits, crushed by the Bladespire and in need of a new weapon, so he set out to make the perfect brew, one to strengthen whoever drinks it and weaken the enemy. Whether it truly works, he could not say until someone carried it up to Bladespire Hold.', 'quest 10545 description (what T''chali did not say: the Bloodmaul in dire straits, the perfect brew)'),
(352238, 2, 0, 255, 'His grudge has names. Grimnok Battleborn led the ogres who buried T''chali and left him to die, and the very next day Korgaah came raiding south from the Bladespire and kicked him in the head where he lay. The witch doctor wants them both dead, and he has waited a long time for his revenge.', 'quest 10543 description (Grimnok led the burial, Korgaah kicked him the next day, T''chali has been waiting for his revenge)'),
(352250, 1, 0, 255, 'The seeker''s vision found the last relic, the Thunderspike, at the back of the Draenethyst Mine, deep in Bloodmaul territory and too far for Rokgah to travel himself. The Bloodmaul must have stolen the spear from the Bladespire.', 'quest 10525 reward text; quest 10526 description'),
(352250, 2, 0, 255, 'With the relics returned to appease the dead, the ghost of Garm Wolfbrother, chieftain of the Thunderlord clan, appeared with news for Rexxar: the Mok''Nathal he seeks have a village to the east beyond the Razor Ridge, and they are in danger.', 'quest 10526 reward text; quest 10718 description and reward text (Garm, last chieftain)'),
(352250, 3, 0, 255, 'Rexxar trusted the word of Garm, last chieftain of the Thunderlord, but was uneasy about how his people would greet him, and sent an envoy to their chief, Leoroxx. The welcome was cold. His father owned him as a son and nothing more, an outsider unwelcome in the village, and Rexxar resolved to open the old chief''s eyes.', 'quest 10614 description; quest 10709 description and reward text'),
(352250, 4, 0, 255, 'Rexxar could not believe that simple ogres would harass the Mok''Nathal for no gain. His hawk Spirit, sent to spy on a Bloodmaul taskmaster and soothsayer, learned the truth: the sons of Gruul are behind it, commanding the Bloodmaul to destroy the Mok''Nathal to win their favor.', 'quest 10714 description and reward text'),
(352251, 1, 0, 255, 'A statuette fell from Dorgok''s dead hand in the likeness of Gorgrom the Dragon-Eater, a son of Gruul. Gorgrom is behind the Bloodmaul plans against Sylvanaar, and since dealing with a gronn takes more than soldiers, Stonewall asks the baron to fashion a trap for him.', 'quest 10797 description and reward text; quest 10798 description'),
(352251, 2, 0, 255, 'First the baron named his price: the sack the gronn Grulloc guards in the Cursed Hollow, which had to be stolen from under the gronn''s nose. Once it was in his hands, Sablemane, whose grudge runs to the slaughter of his own people by the gronn, gave over a trap of dragon fire with which even a gronn might be slain.', 'quests 10721, 10800 (Grulloc''s sack, the price); quests 10785, 10801 descriptions (dragon fire trap, my people, my children)'),
(352251, 3, 0, 255, 'Set at Gorgrom''s altar at Boulder''mok, the trap brought down the Dragon-Eater, and grisly totems made from the heads of his Boulder''mok worshippers were planted around the body, so that the ogres would know the price of seeking to destroy their enemies.', 'quests 10723, 10802 descriptions and reward texts'),
(352251, 4, 0, 255, 'Last came Goc, master of the Bladespire. Rexxar''s wyvern Leokk, freed from his cage in the Bladespire encampment outside Gruul''s Lair, brought back the head of a black dragon from Dragons'' End to enrage the gronn, and at Goc''s altar Rexxar answered the call of his horn and slew the son of Gruul beside his ally.', 'quest 10724 description and reward text; quest 10742 description and reward text'),
(352251, 5, 0, 255, 'For the Alliance the end came at the baron''s own call. After his chosen proxy cut down the toughest Bladespire guarding Gruul''s Lair and their leader Fingrom, Sablemane gave up his signet and came himself to Goc''s altar, shedding his human guise in the battle that killed the master of the Bladespire.', 'quest 10805 description; quest 10806 description and reward text'),
(352252, 1, 0, 255, 'Grulloc, Maggoc and Slaag fell, and Maggoc''s precious chest turned out to be empty, proof to Mog''dorg of the mindless brutality his people face. One gronn remained: Skulloc Soulgrinder, who keeps himself hidden. To coax him out, the grimoire of his teacher, the warlock Vim''gol the Vile, had to be taken from the fire circle near the Broken Wilds where Vim''gol can be summoned.', 'quest 10996 reward text (empty chest); quest 10998 description'),
(352252, 2, 0, 255, 'Its ritual, read aloud at Soulgrinder''s Barrow, forced Skulloc into the world while his ghostly victims tried to smash the Soulgrinder. With the sons dead, Mog''dorg declared the ogres freed from their shackles. Bloodmaul and Bladespire alike gathered to hail their liberator as a new king, while Gruul and Maulgar cowered in their lair, and the new monarch was sent up to Ogri''la.', 'quest 11000 description and reward text; creature_text 22941 (All hail the new king); quest 11009 description'),
(352253, 1, 0, 255, 'Torkus asked for two unstable flasks to give his boys every advantage: one from the fel crystalforge at either forge camp, which he believed took ten apexis shards to make, and one from the crystalforge at Bash''ir Landing, meant to make a boy cleverer still. With both in hand, he shouted for one of his sons and sent him north to the Skyguard Outpost.', 'quest 11030 description and reward text; quest 11061 description, request and reward texts; npc_text 10916 (ten sons)'),
(352254, 1, 0, 255, 'The answer horrified Toshley. The orbs are woven from nether energy and souls, some of them gnome souls, perhaps of the very people who never came home from the north. He demands the death of the Razaani leader, Nexus-Prince Razaan, and the return of the collection of souls he must be keeping.', 'quest 10674 reward text; quest 10675 description'),
(352254, 2, 0, 255, 'Dohgar''s fears proved true. The orbs hold souls, and among them are the souls of Mok''Nathal ancestors. He sent word to Leoroxx at once, and Leoroxx, who trusts his spiritcallers, named it a defilement of his people''s honored dead and called for Razaan''s death.', 'quest 10859 reward text; quest 10865 description; quest 10865 reward text and 10867 description'),
(352254, 3, 0, 255, 'Razaan kept to hiding until the slaughter of his followers drew him out. He was slain, and the collection of souls he had gathered was carried away from the landing, out of the ethereals'' hands.', 'quests 10675, 10867 descriptions and reward texts'),
(352254, 4, 0, 255, 'At Mok''Nathal Village the recovered souls were given to Spiritcaller Dohgar, and the ancestors were released at last to the cleansing fire. Leoroxx counted those who brought them home among his people''s heroes, and wished a thousand plagues upon the ethereals'' brethren.', 'quest 10867 description and reward text'),
(352255, 1, 0, 255, 'Borgrim found the brew vile and swore off it after one sip. Instead he had the rest poured down Bladespire throats to see what would happen, and the answer delighted him: ogres, it seems, will drink anything.', 'quests 10511, 10512 descriptions and reward texts'),
(352255, 2, 0, 255, 'With his trappings restored, Vuuleen sent his helpers against Gorr''Dim, the crafty chieftain of Bladespire Hold, and then had a stolen Bladespire banner planted atop the Bloodmaul''s Northmaul Tower. The ruse worked: Bloodmaul fury now falls on Bladespire Hold instead of Sylvanaar.', 'quests 10517, 10518 descriptions; quest 10518 reward text (pressure relieved on Sylvanaar)'),
(352255, 3, 0, 255, 'T''chali''s brew had a purpose: the Bloodmaul were losing to the Bladespire, and he meant it to strengthen its drinker and weaken the enemy. He tested it on the Bladespire, had Grimnok Battleborn, who led his burial, and Korgaah, who came raiding to kick him in the head, killed, and then cursed the buildings of both clans with a fetish from his grave.', 'quests 10545, 10543, 10544 descriptions and reward texts'),
(352256, 1, 0, 255, 'Nuaar would hear none of it: his people are free to do as they please, he said, and the Cenarion Expedition does not own the mountains. Chawn answered with force against the hewers, and the scholar Samia Inkling, who studies the coven, began gathering nets to catch its blackwhelps alive.', 'npc_text 10533 (Nuaar: no negotiations); quests 10682, 10713; quests 10717, 10747 descriptions'),
(352256, 2, 0, 255, 'The note revealed a planned meeting between Nuaar and Kolphis Darkscale, second in command of the Wyrmcult at the Blackwing Coven. Watcher Moonshade, holding the Wyrmskull Tunnel against the massing cultists, first wanted their leader there, Draaca Longtail, dead, to sow confusion in their ranks.', 'quest 10719 description and reward text; creature_text 21983 (Samia: second-in-command); quests 10894, 10893'),
(352256, 3, 0, 255, 'Draaca fell, and an agent of Evergrove entered the coven disguised as Nuaar. Kolphis berated the false overseer for the trickle of lumber and livestock and let slip that Maxnar the Ashmaw means to wipe out the druids, while Kolphis himself has arranged a truce with the arakkoa so the cult need not fight on another front.', 'quest 10722; npc_text 10541, 10542, 10543 (Kolphis meeting)'),
(352256, 4, 0, 255, 'The Expedition struck first. Maxnar the Ashmaw, one of the dragonkin and patriarch of the cult, was slain in his caverns, and Evergrove and the Ruuan Weald breathe more easily, the coven''s plans foiled whatever its ultimate goals.', 'quest 10748 description and reward text'),
(352257, 1, 0, 255, 'At Veil Lashh the feather spell was cast at last, and it was not what Daranelle expected of magic she had called unnatural: no simple conjuring or enchantment, but some sort of communion or communication. She will need to think on it longer before she can say what the Lashh''an seek by it.', 'quest 10556 reward text'),
(352257, 2, 0, 255, 'Prophecies of the Raven''s return out of the darkest night, heard at the four shrines, troubled Timeon deeply. The arakkoa were peaceful for a long time, he says, and their cult of the Raven was nothing more than a gathering of misfits and madmen, but its power has grown past discounting, and there may be more to this Raven than anyone yet knows.', 'quest 10607 description, request and reward texts; broadcast_text 19475'),
(352257, 3, 0, 255, 'Chawn tried the orb and felt the evil within it give up a lingering memory: the arakkoa are causing the guardian trees of the Raven''s Wood to be possessed by evil spirits. One ancient of lore, Treebole, could not have been touched, and Chawn urges that he be found at once if the wood is to be saved.', 'quest 10825 reward text; quest 10829 description'),
(352257, 4, 0, 255, 'Treebole called for an exorcism. With feathers made from Grishnath orbs and the pinfeathers of dire ravens, the koi-koi spirits were drawn out of the leafbeards and slain, and the evil began to lift from the Raven''s Wood.', 'quest 10830 description and reward text'),
(352258, 1, 0, 255, 'O''Mally mended the mask and found it a Legion communication device, a Felsworn gas mask of the kind Wildlord Antelarion had long been trying to get his hands on. Antelarion saw at once how much trouble it could cause Forge Camp: Anger.', 'quest 10810 reward text; quest 10812 description and reward text'),
(352258, 2, 0, 255, 'Wearing it, an agent slipped into the camp and spoke through the Legion communicator, telling the enraged demon on the other end that the camp had revolted. He ordered every traitor silenced, so the camp''s engineers and attendants were cut down on his behalf, and the blame was then laid on his underling Doomcryer, long suspected of undermining him, who was summoned through the camp''s five obelisks and slain.', 'quests 10819, 10820, 10821'),
(352258, 3, 0, 255, 'Antelarion then turned to a greater danger: Death''s Door, a portal onto the world where the Legion breeds its hounds. Evergrove druids imbued fel cannonballs with nature''s wrath, the Legion''s own fel cannons were turned on the two warp-gates that move and strengthen the void terrors, and Baelmon the Hound-Master, who keeps the portal''s ritual alive, fell with the druids'' help.', 'quests 10910, 10904, 10911, 10912'),
(352259, 1, 0, 255, 'Evidence from Stasis Chamber Alpha confirmed Ameer''s fears: the chambers hold ferocious beasts and creatures from many different worlds, which the Ethereum mean one day to command. Ameer resolved to destroy them all, forging stasis chamber keys from captured prison keys so that each chamber can be opened and whatever lurks within destroyed.', 'quest 10974 reward text; quest 10975 request and reward text'),
(352259, 2, 0, 255, 'Among the spoils of the chambers was a Mark of the Nexus-King, the last piece of a key to the stasis chambers hidden in the Mana-Tombs of Auchindoun. Its glyphs spoke of two final prisons there, one near the entrance and one near Nexus-Prince Shaffar.', 'quest 10976 description and reward text; quest 10977 description');
